 function requestInspection(options={}){const s=session(),method=active;if(!s?.snapshot||s.initializing||s.dirty||s.symmetryPending)return;const {response,...selectionPatch}=options??{};if(Object.keys(selectionPatch).length)s.selection={...selection(),...selectionPatch};clearTimeout(inspectionTimer);s.inspectRequest=(s.inspectRequest||0)+1;const requestId=s.inspectRequest;s.inspectBusy=true;inspectionTimer=setTimeout(()=>{if(active!==method||session()!==s||!shown||requestId!==s.inspectRequest)return;worker.postMessage({type:'explain',session:active,version:s.version,selection:selection(),token:s.trace?.token,phase:s.trace?s.phase:0,response:!!options?.response,explainRequestId:requestId});renderInspector();},40);}
 function requestSymmetry(options={}){const s=session(),method=active;if(!s?.snapshot)return;clearTimeout(inspectionTimer);s.symmetryPending=true;s.inspectRequest=(s.inspectRequest||0)+1;s.inspectBusy=true;s.symmetry=null;pause();inspectionTimer=setTimeout(()=>{if(active!==method||session()!==s||!shown)return;s.inspectRequest=(s.inspectRequest||0)+1;worker.postMessage({type:'symmetry',session:active,version:s.version,selection:selection(),token:s.trace?.token,phase:s.trace?s.phase:0,...(typeof options==='string'?{kind:options}:options),explainRequestId:s.inspectRequest});renderInspector();},40);}
 function renderInspector(){if(!inspector||!session())return;const s=session();inspector.render({snapshot:s.snapshot,trace:s.trace,phase:s.trace?s.phase:0,committed:s.committed,selection:selection(),inspection:s.inspection,busy:s.inspectBusy,symmetryMode,symmetry:s.symmetry});}
